import React, { useState, useEffect } from "react";
import axios from "axios";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import AdminSidebar from "../components/AdminSideBar";
import "./CreateGroupPage.css";

function CreateGroupPage() {
  const [groupNumber, setGroupNumber] = useState("");
  const [projectName, setProjectName] = useState("");
  const [selectedMembers, setSelectedMembers] = useState([]);
  const [supervisor, setSupervisor] = useState("");
  const [evaluator, setEvaluator] = useState("");
  const [allGroups, setAllGroups] = useState([]);
  const [students, setStudents] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [evaluators, setEvaluators] = useState([]);

  // Fetch data on component mount
  useEffect(() => {
    const fetchData = async () => {
      try {
        const [studentsRes, supervisorsRes, evaluatorsRes, groupsRes] = await Promise.all([
          axios.get("http://localhost:5000/api/student"),
          axios.get("http://localhost:5000/api/facultyAdvisor"),
          axios.get("http://localhost:5000/api/evaluator"),
          axios.get("http://localhost:5000/api/group"),
        ]);
        setStudents(studentsRes.data);
        setSupervisors(supervisorsRes.data);
        setEvaluators(evaluatorsRes.data);
        setAllGroups(groupsRes.data);
      } catch (error) {
        console.error("Error fetching data:", error);
      }
    };
    fetchData();
  }, []);

  // Handle group creation
  const handleGroupCreation = async (e) => {
    e.preventDefault();
    if (
      groupNumber.trim() &&
      projectName.trim() &&
      selectedMembers.length > 0 &&
      supervisor &&
      evaluator
    ) {
      try {
        // Create project
        const projectRes = await axios.post("http://localhost:5000/api/project", {
          title: projectName,
          status: "active",
        });
        const projectID = projectRes.data._id;

        // Create group
        const groupRes = await axios.post("http://localhost:5000/api/group", {
          groupNo: groupNumber,
          studentsRegno: selectedMembers.map((s) => s.regNo),
          projectID,
          supervisorID: supervisor,
          evaluatorID: evaluator,
        });

        // Update students' isGrouped status
        await Promise.all(
          selectedMembers.map((student) =>
            axios.patch(`http://localhost:5000/api/student/${student._id}`, {
              isGrouped: true,
            })
          )
        );

        // Refresh data
        const [studentsRes, groupsRes] = await Promise.all([
          axios.get("http://localhost:5000/api/student"),
          axios.get("http://localhost:5000/api/group"),
        ]);
        setStudents(studentsRes.data);
        setAllGroups(groupsRes.data);

        // Reset form
        setGroupNumber("");
        setProjectName("");
        setSelectedMembers([]);
        setSupervisor("");
        setEvaluator("");
      } catch (error) {
        console.error("Error creating group:", error);
        alert("Failed to create group. Please try again.");
      }
    } else {
      alert("Please fill all fields, select members, supervisor, and evaluator.");
    }
  };

  // Handle member selection
  const handleMemberSelection = (student) => {
    if (selectedMembers.some((m) => m._id === student._id)) {
      setSelectedMembers(selectedMembers.filter((m) => m._id !== student._id));
    } else if (selectedMembers.length < 4) {
      setSelectedMembers([...selectedMembers, student]);
    } else {
      alert("You can select up to 4 members only.");
    }
  };

  // Handle group disbanding
  const handleDisbandGroup = async (groupId) => {
    try {
      // Fetch group details
      const groupRes = await axios.get(`http://localhost:5000/api/group/${groupId}`);
      const group = groupRes.data;

      // Update students' isGrouped status
      await Promise.all(
        group.studentsRegno.map((regNo) =>
          axios
            .get(`http://localhost:5000/api/student/regNo/${regNo}`)
            .then((res) =>
              axios.patch(`http://localhost:5000/api/student/${res.data._id}`, {
                isGrouped: false,
              })
            )
        )
      );

      // Delete group
      await axios.delete(`http://localhost:5000/api/group/${groupId}`);

      // Refresh data
      const [studentsRes, groupsRes] = await Promise.all([
        axios.get("http://localhost:5000/api/student"),
        axios.get("http://localhost:5000/api/group"),
      ]);
      setStudents(studentsRes.data);
      setAllGroups(groupsRes.data);
    } catch (error) {
      console.error("Error disbanding group:", error);
      alert("Failed to disband group. Please try again.");
    }
  };

  return (
    <div className="create-group-container">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />
        <div className="main-content">
          <div className="create-group-section">
            {/* Group Form */}
            <div className="form-container">
              <h2>Create a New Group</h2>
              <form onSubmit={handleGroupCreation}>
                <div className="input-group">
                  <label htmlFor="group-number">Group Number</label>
                  <input
                    type="text"
                    id="group-number"
                    value={groupNumber}
                    onChange={(e) => setGroupNumber(e.target.value)}
                    placeholder="Enter group number"
                    required
                  />
                </div>
                <div className="input-group">
                  <label htmlFor="project-name">Project Name</label>
                  <input
                    type="text"
                    id="project-name"
                    value={projectName}
                    onChange={(e) => setProjectName(e.target.value)}
                    placeholder="Enter project name"
                    required
                  />
                </div>
                <button type="submit" className="submit-button">
                  Create Group
                </button>
              </form>
            </div>

            {/* Student Table */}
            <div className="student-selection">
              <h3>All Students</h3>
              <table>
                <thead>
                  <tr>
                    <th>Select</th>
                    <th>Name</th>
                    <th>Reg. No</th>
                  </tr>
                </thead>
                <tbody>
                  {students.map((student) => (
                    <tr key={student._id}>
                      <td>
                        <input
                          type="checkbox"
                          checked={selectedMembers.some((m) => m._id === student._id)}
                          onChange={() => handleMemberSelection(student)}
                          disabled={student.isGrouped}
                        />
                      </td>
                      <td>{student.studentName}</td>
                      <td>{student.regNo}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Supervisor & Evaluator Dropdowns */}
            <div className="supervisor-evaluator-selection">
              <h3>Select Supervisor and Evaluator</h3>
              <table>
                <thead>
                  <tr>
                    <th>Role</th>
                    <th>Name</th>
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    <td>Supervisor</td>
                    <td>
                      <select
                        value={supervisor}
                        onChange={(e) => setSupervisor(e.target.value)}
                        className="select-dropdown"
                        required
                      >
                        <option value="">-- Select Supervisor --</option>
                        {supervisors.map((s) => (
                          <option key={s._id} value={s._id}>
                            {s.Name}
                          </option>
                        ))}
                      </select>
                    </td>
                  </tr>
                  <tr>
                    <td>Evaluator</td>
                    <td>
                      <select
                        value={evaluator}
                        onChange={(e) => setEvaluator(e.target.value)}
                        className="select-dropdown"
                        required
                      >
                        <option value="">-- Select Evaluator --</option>
                        {evaluators.map((e) => (
                          <option key={e._id} value={e._id}>
                            {e.name}
                          </option>
                        ))}
                      </select>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>

            {/* Created Groups */}
            <div className="groups-list">
              <h3>Created Groups</h3>
              {allGroups.length > 0 ? (
                <table>
                  <thead>
                    <tr>
                      <th>Group No</th>
                      <th>Project</th>
                      <th>Supervisor</th>
                      <th>Evaluator</th>
                      <th>Members</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {allGroups.map((group) => (
                      <tr key={group._id}>
                        <td>{group.groupNo}</td>
                        <td>{group.projectID}</td>
                        <td>{group.supervisorID}</td>
                        <td>{group.evaluatorID}</td>
                        <td>
                          <ul>
                            {group.studentsRegno.map((regNo, idx) => (
                              <li key={idx}>{regNo}</li>
                            ))}
                          </ul>
                        </td>
                        <td>
                          <button
                            onClick={() => handleDisbandGroup(group._id)}
                            className="disband-button"
                          >
                            Disband Group
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <p>No groups have been created yet.</p>
              )}
            </div>
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default CreateGroupPage
